def f(xs):
    if not xs:
        return []
    n = xs[-1] % len(xs)
    return xs[n:] + xs[:n]

def f(xs):
    if len(xs) < 2:
        return xs[:]
    m, n = xs[:2]
    return [x for i, x in enumerate(xs, 1) if not m <= i <= n]

def f(xs):
    if not xs:
        return []
    lo, hi = min(xs), max(xs)
    return [lo if x == hi else x for x in xs]

def f(xs):
    if not xs:
        return []
    out = xs[:]
    target = xs[0]
    if 0 <= target < len(out):
        out[target] = len(out)
    return out[1:]

def f(xs):
    out = []
    at_start = True
    for x in xs:
        if x == 0:
            at_start = True
        elif at_start:
            out.append(x)
            at_start = False
    return out

def f(xs):
    if not xs:
        return []
    if xs[0] == 0:
        return xs[:]
    return [x for x in xs if x % xs[0] != 0]

def f(xs):
    if not xs:
        return []
    tail = xs[1:]
    if not tail:
        return []
    count = max(0, xs[0])
    limit = min(10000, len(tail) * count)
    whole, remainder = divmod(limit, len(tail))
    return tail * whole + tail[:remainder]
